"1agkf6n": "जिस ऐक्सिस को इसने यॉ समझा वह एक बार भी नहीं हिला, जबकि एक अनजान स्टिक एक सिरे से दूसरे सिरे तक घुमाई गई है। इसका मतलब रेडियो अपने चैनल अंदाज़े से अलग क्रम में भेज रहा है, और जो हिस्सा खो गया है वह यॉ है। कैलिब्रेशन में क़रीब एक मिनट लगता है और यह पेज को बताता है कि कौन सा ऐक्सिस क्या है।",
