"1m2xvti": "फ़्लाइट मोड",
"xjyq13": "एक्रो: स्टिक घूमने की दर हैं, हाथ हटाने पर रुख़ बना रहता है। एंगल: स्टिक झुकाव हैं, Betaflight की 60 डिग्री सीमा तक, हाथ हटाने पर सीधा हो जाता है। यह रेस कीबोर्ड पर उड़ाई जाती है, जिसकी अपनी पसंद होती है (क्वाड में कीबोर्ड रेस); यह पंक्ति उसी को बदलती है। उड़ान में M भी इसे बदलता है।",
"1r5ubv6": "एक्रो: स्टिक घूमने की दर हैं, हाथ हटाने पर रुख़ बना रहता है। एंगल: स्टिक झुकाव हैं, Betaflight की 60 डिग्री सीमा तक, हाथ हटाने पर सीधा हो जाता है, यॉ दर ही रहता है। फ़्लिप और रोल के लिए एक्रो चाहिए। उड़ान में M भी इसे बदलता है, और यह बना रहता है।",
"x7vih9": "एक तरफ़ कितने, बॉट कितना अच्छा खेलते हैं, और यह कब ख़त्म होता है।",
