"1t8ovw1": "यहाँ अकेले हाँकते रहो, न बॉट, न घड़ी।",
"1087r08": "बॉट, वे कितने अच्छे हैं, रिबन कितने लंबे हैं और राउंड।",
"1206cs3": "यहाँ बिना रिबन और बिना बॉट के उड़ते रहो।",
"899bgs": "बॉट, वे कितने अच्छे हैं, राउंड और चोट कितनी ज़ोर से लगती है।",
