"wyh1np": "क्वाड कितना भारी लगता है। दाईं ओर भारी: थ्रॉटल काटते ही गिरता है और जंप के ऊपर टिकता नहीं। बाईं ओर हल्का, और तैरता है। {0} वह क्वाड है जैसा वह आता है; लैप के बीच में बदलने पर लैप रद्द हो जाता है, और {1} से हटकर उड़ाया गया लैप सार्वजनिक बोर्ड पर तुम्हारे नाम के साथ अपना वज़न लेकर जाता है।",
