"ior56v": "मोटर पावर",
"1x4irmq": "मोटर एक वोल्ट पर कितनी रफ़्तार बनाती हैं, यानी उनका KV। बाईं ओर नरम: हल्का पंच और कम टॉप स्पीड। दाईं ओर ज़ोरदार, जिससे बैटरी ज़्यादा गिरती है और क्वाड स्टिक पर नीचे होवर करता है। {0} वह क्वाड है जैसा वह आता है, पायलटों के भेजे ट्यून से तय। लैप के बीच में बदलने पर लैप रद्द हो जाता है, और {1} से हटकर उड़ाया गया लैप सार्वजनिक बोर्ड पर Tuned टैग के साथ जाता है।",
"1bsvonq": "डिफ़ॉल्ट रूप से बंद। चालू होने पर, क्वाड ज़मीन पर हो तब {0} स्टिक के बीच वज़न के साथ दिखते हैं, और अपने स्लाइडर पर उड़ाई गई उड़ान एक सवाल पर ख़त्म होती है: क्या यह स्टॉक क्वाड से बेहतर लगा? जब तक तुम हाँ न कहो, कुछ नहीं भेजा जाता। बंद होने पर स्लाइडर कुछ भी कहें, क्वाड वैसा ही उड़ता है जैसा वह आता है। लैप के बीच में बदलने पर, अगर तुम्हारा उड़ता क्वाड बदलता है तो लैप रद्द हो जाता है।",
"5xvgod": "ट्यून की गई उड़ान के बाद पूछो",
"1siorg1": "जब अपने स्लाइडर पर उड़ाई गई उड़ान ख़त्म हो, तो पूछो कि क्या वह स्टॉक से बेहतर लगी। तुम हमेशा ना कह सकते हो, और हाँ के बिना कुछ नहीं भेजा जाता। बंद होने पर कभी नहीं पूछता; स्लाइडर फिर भी काम करते हैं।",
"187fv0s": "ट्यून के काम को बताओ कि क्वाड कैसा उड़ता है। एक शब्द काफ़ी है; तुम्हारा ट्यून, PID बदलाव और रेट्स साथ जाते हैं।",
