"unl4q1": "चौड़ा ज़्यादा दिखाता है, संकरा बड़ा करके दिखाता है। संकरा वही है जो FPV लेंस फ़्रेम के बीच के साथ करता है; स्टैंडर्ड चौड़ाई के लिए उसमें से कुछ लौटाता है; सबसे चौड़ा उतना चौड़ा है जितना यह तस्वीर ईमानदारी से हो सकती है, और गेट उसमें छोटे दिखेंगे।",
