"1yc8yfn": "उड़ान स्क्रीन पर स्टिक के बीच का वज़न स्लाइडर ठीक इसी शिकायत के लिए है: यह क्वाड का उठाया वज़न बदलता है, तो थ्रॉटल काटने पर वह टिके रहने की जगह गिरता है। तुम्हारा {0} प्रतिशत पर है। और दाईं ओर ले जाने पर थ्रॉटल काटते ही वह जल्दी गिरता है और छोटे पंच के बाद कम ऊपर तैरता है। होवर इसके साथ स्टिक पर ऊपर जाता है, स्टॉक पर {1} प्रतिशत से {3} पर {2} तक। हमारा इंतज़ार करने से पहले इसे खींचकर देखो, और इस पर उड़ाया लैप सार्वजनिक बोर्ड पर तुम्हारे नाम के साथ अपना वज़न लेकर जाता है।",
"r74boy": "बिना थ्रॉटल सीमा के यह क्वाड स्टिक के {0} प्रतिशत पर होवर करता है, इसलिए लगभग सारी चाल होवर के ऊपर है। रेट्स, थ्रॉटल सीमा, 75 प्रतिशत करने पर होवर {1} प्रतिशत पर आ जाता है और बारीक कंट्रोल लौट आता है, बिना उस चढ़ाई को खोए जो घर के अंदर काम आती है। हमारा इंतज़ार करने से पहले आज़माने लायक़ है।",
"1xpffsm": "उड़ान के एहसास की ट्यूनिंग चालू करो",
"194uxup": "उड़ान के एहसास की ट्यूनिंग चालू है। जब तुम ज़मीन पर हो, स्टिक के बीच वज़न के पास {0} {1}। अगर कोई सेटिंग स्टॉक से बेहतर लगे तो उड़ान के अंत में पूछा जाता है कि उसे भेजना है या नहीं।",
"1elhpti": "ख़ुद बदलना चाहते हो? उड़ान के एहसास की ट्यूनिंग ज़मीन पर रहते हुए वज़न के पास {0} रखती है: {1}। अगर कोई सेटिंग स्टॉक से बेहतर लगे तो उड़ान के बाद हमें आँकड़े भेज सकते हो। जब तक तुम चालू न करो, बंद रहती है, और तुम्हारी हाँ के बिना कुछ नहीं भेजा जाता।",
