"1m53rax": "स्टिक कितनी दूर तक जाती हैं, और थ्रॉटल लिमिट। ये तुम्हारी हैं, ट्यून की नहीं। यहाँ बदलने पर क्वाड वहीं रहता है और घड़ी चलती रहती है।",
