"1v6l9n2": "इस रन में टेस्ट हुक इस्तेमाल हुए, इसलिए यह उड़ाकर बनाया गया स्कोर नहीं है और बोर्ड इसे नहीं लेगा।",
"grcded": "इस रन के दौरान वज़न बदला, इसलिए बोर्ड के दिखाने के लिए कोई एक वज़न नहीं है। एक ही वज़न पर फिर से उड़ाओ।",
"tbtfzi": "ट्यून की हुई उड़ान, बोर्ड पर पोस्ट नहीं हुई। हवा की पकड़ या मोटर पावर 100 से हटाकर लगाई गई ट्रिक उस क्वाड से अलग क्वाड पर हैं जो बाकी सबने उड़ाया। दोनों को वापस 100 पर करो और फिर से उड़ाओ।",
"1pz4yp7": "{1} ट्रिक{2}{3} से {0}। बोर्ड पर हर पायलट की एक एंट्री, और सिर्फ़ तुम्हारा बेस्ट।",
