"1wju8o1": "शेयर कार्ड सेव हो गया",
"13caij": "शेयर कार्ड सेव करो",
"3o9ejy": "जिस रन में बनाने लायक कुछ नहीं, उसका कार्ड नहीं होता। एक ट्रिक, एक गैप, एक स्किम या एक टेल से यहाँ कार्ड आ जाता है।",
"e5ghz6": "{0} नाम से सेव हुआ। एक और कॉपी के लिए यह पंक्ति फिर चुनो।",
"14yxwli": "रन एक मांगा पेज के रूप में, स्कोर के साथ, 1200 गुणा 630, वही साइज़ जो लिंक प्रीव्यू में लगता है। JPEG के रूप में सेव होता है, जहाँ चाहो पोस्ट करो।",
"1k0zug5": "हर प्रकाशित ट्रैक और मैप, और उन पर उड़ाए गए टाइम। नए टैब में खुलता है।",
