"cdtta": "नीचे के नंबर किस रेट सिस्टम में हैं। पाँचों Betaflight के अपने हैं और पाँचों उड़ते हैं: कर्व fc/rc.c में इसी एक फ़ील्ड से चुना जाता है। Actual Betaflight 4.5 का डिफ़ॉल्ट है और वही है जिसका मैक्स रेट कॉलम स्टॉप पर ठीक वही मतलब रखता है जो लिखा है। इसे बदलने पर उस सिस्टम के अपने डिफ़ॉल्ट लोड होते हैं, क्योंकि Betaflight का RC rate 1.00 और Actual की सेंटर सेंसिटिविटी 70 एक ही सेव किया गया नंबर हैं पर एक ही सेटिंग नहीं।",
"1bi0zn2": "पिच अलग",
"3xx6vi": "चालू। पिच के अपने तीन नंबर हैं और ग्राफ़ पर अपना कर्व है। इसे बंद करने पर रोल पिच पर कॉपी हो जाता है।",
"c4nhs2": "बंद। रोल और पिच नंबरों का एक ही सेट साझा करते हैं, ज़्यादातर क्वाड ऐसे ही सेट होते हैं और Betaflight भी ऐसे ही आता है। पिच को अपने नंबर देने के लिए इसे चालू करो।",
"s1apod": "रोल और पिच",
"16y9oqq": "थ्रॉटल लिमिट",
"18dkbs9": "बंद। इस क्वाड का थ्रस्ट और वज़न का अनुपात लगभग नौ और एक है और यह स्टिक के {0} प्रतिशत पर होवर करता है, इसलिए ज़्यादातर ट्रैवल होवर से ऊपर है। लिमिट लगाने से पूरी स्टिक छोटी स्केल हो जाती है और बारीकी लौट आती है।",
"74eytz": "Betaflight SCALE लिमिट: पूरी स्टिक {0} प्रतिशत का कमांड देती है, और पूरा ट्रैवल उसके नीचे फिर से बँट जाता है। होवर स्टिक के लगभग {1} प्रतिशत पर चला जाता है, इसलिए थ्रॉटल कम संवेदनशील रहता है।",
"9pydfr": "{0} यह क्वाड फ़ैक्टरी कर्व पर स्टिक के {1} प्रतिशत के पास होवर करता है।",
"1sgjqd3": "प्रीसेट",
"1m38alp": "सेव नहीं हुआ",
"2xpdfb": "प्रीसेट के रूप में सेव करो",
"1i6mwh9": "प्रीसेट मिटाओ",
"u3znvf": "{0} को भूल जाओ। यह ब्राउज़र ही इकलौती कॉपी है, इसलिए इसे वापस नहीं लाया जा सकता। नंबर क्वाड पर रहते हैं; सिर्फ़ सेव की हुई प्रोफ़ाइल जाती है।",
"17l6uak": "पहले एक प्रीसेट लोड करो। यह वह प्रोफ़ाइल मिटाता है जिस पर नीचे की पंक्तियाँ उड़ रही हैं, और वे अभी किसी सेव की हुई प्रोफ़ाइल पर नहीं उड़ रहीं।",
"p52kwi": "डिफ़ॉल्ट पर लौटो",
