"x624ug": "{0} में यह {1} पर आता है; इसे वापस वहीं रखने पर बदलाव भुला दिया जाता है।",
"18oympv": "ट्यून लाया और लगाया जा रहा है। मॉड्यूल के वापस पढ़ते ही इसके स्लाइडर दिखेंगे।",
"1grap3n": "PID सीधे सेट करो",
"c5voz3": "चालू। स्लाइडर बंद हैं (simplified_pids_mode OFF, जैसा Configurator का एक्सपर्ट मोड करता है) और नीचे की टेबल ही उड़ती है। इसे बंद करने पर स्लाइडर लौट आते हैं और टेबल याद रहती है।",
"15ryevg": "बंद। नीचे के स्लाइडर फ़र्मवेयर की अपनी सरल ट्यूनिंग से PID चलाते हैं। हर वैल्यू खुद टाइप करने के लिए इसे चालू करो, ठीक वहीं से शुरू करके जो अभी उड़ रहा है।",
"cv7xcu": "Betaflight के ट्यूनिंग स्लाइडर",
"qfjx36": "फ़र्मवेयर बेंच: फ़िल्टर, फ़ीचर और हर फ़र्मवेयर की, सिर्फ़ PID नहीं। Configurator जैसी बनावट। CLI पेस्ट नहीं है।",
"3owtby": "ट्यून की अपनी वैल्यू पर वापस",
"idb6of": "{0} के सारे स्लाइडर और हाथ से सेट किए PID भुला देता है और ट्यून को वैसे उड़ाता है जैसी वह आती है। बाकी ट्यून के बदलाव रखे जाते हैं।",
"1jhnqh8": "{0} पहले से अपनी वैल्यू पर उड़ रही है।",
"dfkhrn": "{0} लोड हो रही है।",
"x90o0f": "{0}, PID हाथ से सेट। मॉड्यूल से वापस पढ़ा गया।",
"1lxpdkl": "तुम्हारे स्लाइडर से गुज़री {0}। मॉड्यूल से वापस पढ़ा गया; नॉच स्टॉक 4.5.1 है।",
"60528h": "{0}, जैसी आती है। मॉड्यूल से वापस पढ़ा गया; नॉच स्टॉक 4.5.1 है।",
"boibkp": "सेव नहीं हुआ",
"1q384zq": "3D मोड चालू करें?",
"1bhsb37": "सिर्फ़ 3D उड़ान के लिए। मोटर दोनों तरफ़ घूमती हैं: थ्रॉटल का बीच शून्य थ्रस्ट है और नीचे का हिस्सा तुम्हें उल्टा उड़ाता है, इसलिए जब तक तुम इसे सेटिंग्स, पायलट, 3D मोड में फिर बंद नहीं करते, सामान्य उड़ान टूटी हुई लगेगी।",
"v65w1o": "बंद रहने दो",
"u2bdti": "3D चालू करो",
"7g0dlj": "3D में थ्रॉटल का बीच शून्य थ्रस्ट है और नीचे का हिस्सा तुम्हें उल्टा उड़ाता है, इसलिए सामान्य उड़ान टूटी हुई लगती है। इसे गलती से चालू करना आसान था। तभी चालू रखो जब तुम 3D उड़ाते हो।",
"mxrvnc": "3D बंद करो",
"1s8d24o": "3D चालू रखो",
"avqznd": "इस तरह उड़ाए गए लैप सार्वजनिक बोर्ड पर Tuned टैग के साथ पोस्ट होते हैं।",
"ohro0a": "रियलिस्टिक फ़िज़िक्स",
"s62yi0": "{0} के लिए चालू, प्रयोगात्मक: यह असली ग्रैविटी में अपने सही वज़न पर उड़ता है। यह ज़्यादा खुलकर घूमता है, हवा प्रॉप को वैसे ही धकेलती है जैसे बाहर धकेलती है, वॉश वहीं टिका रहता है जहाँ तुमने छोड़ा, नीचे होवर करने पर ज़मीन सहारा देती है, पंच पर बैटरी सैग करती है, और फ़्रीस्टाइल में वह रीसेट करने तक घटती जाती है। इसका घूमना, मोटर और बैटरी दो असली क्वाड के फ़्लाइट लॉग से मिलाए गए हैं; बाकी हिसाब से निकाला गया है, नापा नहीं गया। रियलिस्टिक लैप का अपना अलग बेस्ट लैप रहता है।{1} {2} को वैसे उड़ाने के लिए जैसे वह यहाँ हमेशा उड़ा, इसे बंद करो। लैप के बीच में बदलने पर वह लैप रद्द हो जाता है।",
"bugmc9": "{0} के लिए बंद: वही उड़ान जो यहाँ हमेशा थी। प्रयोगात्मक असली दुनिया के मॉडल के लिए इसे चालू करो: सही वज़न और ग्रैविटी, ज़्यादा खुला घुमाव, प्रॉप पर ज़्यादा सच्ची हवा, वॉश जो वहीं टिका रहता है जहाँ छोड़ा, ज़मीन का सहारा, और बैटरी जो सैग करती है और फ़्रीस्टाइल में घटती जाती है।{1} हर क्वाड अपना जवाब खुद रखता है।",
"qzitkf": "रियलिस्टिक फ़िज़िक्स चालू है",
"11c30rz": "फ़ाइव इंच अब एक प्रयोगात्मक असली दुनिया के मॉडल पर उड़ता है, जो असली क्वाड के फ़्लाइट लॉग से मिलाया गया है। इसका वज़न असली क्वाड जितना है, इसलिए होवर थ्रॉटल पर नीचे बैठता है और यह अपनी रफ़्तार बनाए रखता है। यह ज़्यादा खुलकर घूमता है, मोटर जवाब देने में एक पल लेती हैं, और पंच करने पर बैटरी सैग करती है। फ़्रीस्टाइल में बैटरी घटती भी है, और रीसेट से नई मिलती है। तुम्हारे पुराने बेस्ट लैप रखे हैं और पुराने एहसास के साथ लौट आते हैं। इसे कभी भी बदलने के लिए: सेटिंग्स, पायलट, रियलिस्टिक फ़िज़िक्स।",
