"1aa3oyb": "थ्रॉटल को लगभग 20 प्रतिशत के पार पंच करो। होल्ड छूटता है, प्रॉप हवा पकड़ते हैं, और तुम उड़ रहे हो। लॉन्च के बाद L फिर दबाने से यह रीसेट होता है।",
"14arqvb": "ऊपर का ऐरो आगे पिच है। W थ्रॉटल है। लॉन्च कंट्रोल होल्ड के लिए तुम्हें एक्रो में ले जाता है, फिर निकलने के बाद तुम्हारा अपना मोड लौट आता है।",
"r89zwp": "वही क्रम जो असली बोर्ड पर होता है। L मोड स्विच है। launch_angle_limit और launch_trigger_throttle_percent को क्वाड के अंदर फ़र्मवेयर बेंच पर बारीकी से सेट करो।",
"1wrrqt3": "अगर तुम ब्लॉक पर पलट जाओ, तो TURTLE MODE संभाल लेता है। पलटने के लिए पिच या रोल दो। टाइमिंग मिलाने की ज़रूरत नहीं। स्टिक बीच में लाओ, फिर L दबाकर दोबारा लॉन्च करो।",
"1x7j2uc": "लॉन्च कंट्रोल, अगर तुमने इसे क्वाड में चालू किया है। पिच, बीच में, पंच।",
"1xmpyfk": "उड़ान में एंगल और एक्रो बदलता है, और पसंद याद रखता है।",
