"1m6rglx": "हर किसी की एक अच्छी तरफ़ होती है। यह लेसन दूसरी तरफ़ के लिए है।",
"1c1xhrj": "अपनी आसान तरफ़ एक रोल।",
"12dhcq9": "समतल उड़ो, वापस ऊपर चढ़ो।",
"tjwcvh": "दूसरी तरफ़ एक रोल।",
"6crrif": "हर तरफ़ एक रोल",
"xbpbzg": "बायाँ, फिर दायाँ, या इसका उल्टा।",
"rhydal": "दोनों रोल के बीच फिर से ऊँचाई ले लो।",
"n7pdfl": "डबल",
"1m0wnhv": "बिना रुके दो पूरे चक्कर: एक डबल फ़्लिप या एक डबल रोल।",
"to0pnn": "दो बार घूमने के लिए दोगुनी ऊँचाई चाहिए और स्टिक को उससे ज़्यादा देर पकड़े रखने की हिम्मत जितना ठीक लगता है।",
