"qkwbo5": "दूसरे पर छोड़ो, और थाम लो।",
"1f6vp2l": "खूब ऊँचाई।",
"qem140": "एक डबल फ़्लिप या रोल",
"1slllpy": "दो चक्कर तक स्टिक पकड़े रखो।",
"czabiw": "और ऊँचे से शुरू करो। डबल में तुम्हारी सोच से ज़्यादा ऊँचाई जाती है।",
"pqwd4i": "टुकड़ों वाले फ़्लिप और रोल",
"ls0z0x": "घुमाव को वहीं रोकना जहाँ तुम चाहो: नाइफ़ एज, उल्टा, और कदम दर कदम घुमाव।",
"1ugfln1": "चौथाई रोल करके करवट पर आओ, एक सेकंड पकड़ो, और रोल करके वापस समतल हो जाओ।",
"o1ksuq": "घुमाव को ठीक वहीं रोकना जहाँ तुम चाहो, हर फ़्रीस्टाइल ट्रिक के नीचे का हुनर है। नाइफ़ एज पहला ठहराव है।",
