"xjpzz8": "चौथाई रोल, फिर करवट पर रुकने के लिए स्टिक बीच में लाओ।",
"1hjct17": "पकड़े रखो, फिर रोल करके समतल हो जाओ।",
"1fu3p0o": "ऊँचाई और कुछ रफ़्तार।",
"o01k4j": "नाइफ़ एज 1 s पकड़ो",
"1ppeqlf": "चौथाई रोल, फिर बीच में।",
"1jstefd": "वापस समतल",
