"18maw0u": "टुकड़ों वाला रोल",
"7h496l": "दो आधों में एक रोल: आधा रोल, उल्टे होकर साफ़ ठहराव, फिर उसी तरफ़ बाकी आधा।",
"keol2n": "टुकड़ों में किया गया घुमाव दिखाता है कि स्टिक तुम्हारे काबू में है, तुम उसके नहीं। जज इसे टुकड़ों वाला रोल कहते हैं।",
"n1rbe7": "आधा रोल और उल्टे होकर रुको।",
"gpjs1c": "वहाँ एक ताल तक पकड़ो: \"एक\" गिनो।",
"6qlriv": "दूसरा आधा, उसी दिशा में।",
"amf75b": "एक टुकड़ों वाला रोल",
"9wzu7i": "आधा, रुको, आधा, उसी तरफ़।",
"1f5mf7j": "ठहराव उल्टे होने पर है: वहाँ थ्रॉटल कम, और दूसरे आधे के बाद थाम लो।",
"j1rvmu": "टुकड़ों वाला फ़्लिप",
"129jcsx": "दो आधों में एक फ़्लिप: आधा फ़्लिप, उल्टे होकर साफ़ ठहराव, फिर उसी तरफ़ बाकी आधा।",
"1eg8l37": "वही अनुशासन पिच एक्सिस पर, जहाँ रुकना कठिन है क्योंकि नोज़ ज़मीन की ओर होती है।",
"3xc4n2": "बहुत ऊँचा चढ़ो, पहले की किसी भी ट्रिक से ऊँचा, फिर आगे आधा फ़्लिप करके उल्टे रुको।",
"1qpsca5": "एक ताल पकड़ो।",
"hy8tdy": "दूसरा आधा, उसी दिशा में, फिर थाम लो।",
"17542cn": "एक टुकड़ों वाला फ़्लिप",
"1lfz2rv": "और ऊँचाई। टुकड़ों वाला फ़्लिप देर तक ज़मीन की ओर मुँह किए रहता है।",
"1eh1588": "आधा रोल करके उल्टे, एक ठहराव, और जिस तरफ़ से आए उसी तरफ़ आधा रोल वापस।",
"1e2q1z7": "रिवाइंड एक घुमाव को पलट देता है: वही एक्सिस, दूसरी दिशा। यह पहली ट्रिक है जो ट्रिक जैसी दिखती है।",
"kbxfoa": "जिस तरफ़ से आए उसी तरफ़ आधा रोल वापस।",
