"1mht6c2": "आधा, रुको, आधा वापस।",
"1dtgvip": "टुकड़ों वाले रोल जैसा ही, पर दूसरा आधा उल्टी तरफ़ वापस जाता है।",
"i4b58z": "गेट",
"1icydtp": "पाँच फ़ुट के गेट, वही साइज़ जो रेसर उड़ाते हैं। एक गेट दोनों तरफ़ से, एक बुनाई, ऊपर से डाइव, एक स्टैक और एक हेयरपिन।",
"112p6bd": "जाओ और लौटो",
"1enqkne": "गेट से बाहर, दूर वाले झंडे का चक्कर, उसी गेट से उल्टी तरफ़ वापस, पैड के पीछे वाले झंडे का चक्कर। दो बार।",
"1orv9cz": "पाँच फ़ुट का गेट दूसरे अध्याय वालों की आधी चौड़ाई का है। एक ही गेट को दोनों तरफ़ से उड़ाकर तुम किसी भी ओर से सीध में आना सीखते हो।",
"vq2hon": "पैड से सीध में आओ और सीधे पार जाओ।",
"1gopj6u": "दूर वाले झंडे को उसकी हरी तरफ़ से घूमो और लौट आओ।",
"1gsilkb": "गेट से फिर उल्टी तरफ़ से गुज़रो, फिर अपने पीछे वाले झंडे का चक्कर लगाओ।",
"13zbt9i": "दो लैप, दोनों तरफ़ से",
"1yo76u6": "गेट के लिए धीमे हो जाओ और उसके बाद तेज़। धीरे से पार होना तेज़ी से टकराने से बेहतर है।",
"15bltj1": "बुनाई",
"1bpsyp7": "मैदान में पाँच गेट, हर एक पिछले के बगल में, फिर झंडे का चक्कर लगाकर पहले गेट पर वापस।",
"131o8ra": "गेट शायद ही कभी सीधी लाइन में होते हैं। यहाँ हर गेट एक छोटा मोड़ है, और हर मोड़ अगले की तैयारी करता है।",
"l09tkb": "पहले गेट से गुज़रो, फिर अगले की ओर धीरे से रोल करो।",
"r8xglr": "इस गेट से निकलते ही अगले गेट को देखो।",
"n7fud3": "अंत में झंडे का चक्कर लगाओ और पहले गेट पर वापस उड़ो।",
"siffl6": "बुनाई का एक लैप",
"xw3wrn": "अगले गेट को देखो, इसे नहीं।",
"4a6lu": "चौड़ी लाइन: हर मोड़ गेट से पहले शुरू करो, उसके बाद नहीं।",
"1xffg1a": "डाइव इन",
