"9pdvnw": "डाइव गेट नीचे की ओर उड़ाया जाता है, इसलिए थ्रॉटल कम होता है और क्वाड ज़मीन की ओर होता है। यह पहला गेट है जिसमें थ्रॉटल की ज़रूरत स्टिक जितनी ही है।",
"1lt0ivw": "पहले गेट से निकलते हुए चढ़ो: डाइव गेट सिर की ऊँचाई से ऊपर है।",
"9vnhdo": "ऊपर से पार, नोज़ नीचे, थ्रॉटल कम, और उसमें से गिरते हुए निकलो।",
"1byzug2": "नीचे थ्रॉटल से थाम लो और आख़िरी गेट के लिए मुड़ो।",
"9q4wit": "डाइव वाला एक लैप",
"17k8dem": "डाइव गेट के ऊपर, फिर उसमें से नीचे।",
"khv1aj": "डाइव को पहले थामो: पार होते ही थ्रॉटल बढ़ाओ।",
