"v2zy3g": "दो छेद, एक के ऊपर एक, ऐसा गेट है जो लाइन के साथ ऊँचाई भी माँगता है। ऊँचाई थ्रॉटल है।",
"j103kr": "ऊपर वाले छेद तक पहुँचने से पहले उसकी ऊँचाई पर चढ़ो।",
"6k1azy": "झंडे का चक्कर लगाओ, फिर नीचे रहकर लौटो।",
"18dprks": "नीचे वाले छेद से सपाट और स्थिर होकर गुज़रो।",
"hojfk2": "ऊपर, फिर नीचे",
"rym8fu": "जलता हुआ छेद अगला है।",
"1bpiray": "वहाँ पहुँचने से पहले छेद की ऊँचाई पर आ जाओ, उसके अंदर नहीं।",
