"7cukoz": "गैप से ट्रिक",
"1xwe34z": "एक कॉम्बो जिसमें एक नाम वाला गैप और एक ट्रिक जुड़े हों: गैप से निकलो और सीधे फ़्लिप, रोल या Powerloop में।",
"f6tckd": "गैप से ट्रिक, यह एक वाक्य में फ़्रीस्टाइल लाइन है। ट्रिक गैप से पहले सोचनी पड़ती है, क्योंकि उसके बाद सोचने का समय नहीं होता।",
"3gbvxn": "ऐसा गैप चुनो जिसके बाद खुली हवा हो: बिलबोर्ड या फ़ुटब्रिज।",
"1864tje": "उससे निकलो, फिर सीधे अपनी ट्रिक में।",
"1b4elaf": "उसे लैंड करो और कॉम्बो बैंक करने के लिए साफ़ उड़ते रहो।",
"g6h1uw": "एक गैप और एक ट्रिक, जुड़े हुए",
"zolhgc": "पहले गैप, फिर ट्रिक।",
"lshhpa": "गैप के बाद और ट्रिक से पहले ऊपर चढ़ो। ऊँचाई ही ट्रिक को पूरा होने देती है।",
"r7bmb7": "बोर्ड के Infinity Loops मैप पर नब्बे सेकंड, पॉइंट के लिए उड़ो। कम से कम 2,000 बैंक करो।",
"pmn0bp": "किसी और के मैप पर फ़्रीस्टाइल रन का मतलब है वे लाइनें ढूँढना जो उसके बिल्डर ने छिपाई हैं। 90%er Gap सबसे ज़्यादा देता है, अगर तुम उसे ढूँढ सको।",
"1tn9e8b": "एक बार घूमकर देखो कि वहाँ क्या है।",
"mob5uv": "पास-पास की दो या तीन चीज़ें ढूँढो और उन्हें जोड़ो।",
"ye4weg": "क्रैश करने से पहले कॉम्बो बैंक कर लो।",
"cwy0ng": "बोर्ड से, Infinity Loops का बनाया।",
"12bujxp": "90 सेकंड में 2,000 पॉइंट बैंक करो",
"1j3tc2e": "लाइनें ढूँढो: एक कॉम्बो में दो गैप और एक ट्रिक, तीनों अलग-अलग करने से ज़्यादा देते हैं।",
"f8era": "क्रैश होने पर बन रहा कॉम्बो चला जाता है। उसे बैंक करो, फिर दोबारा चलो।",
"y0typ6": "Infinity Loops के बनाए Heads के घर के चारों ओर नब्बे सेकंड, पॉइंट के लिए उड़ो। कम से कम 2,000 बैंक करो।",
"1ncd29p": "Heads का अपना घर: दरवाज़े, खिड़कियाँ, बेसमेंट और आँगन। यहाँ फ़्रीस्टाइल रन इन सबके बीच से गुज़रती एक लाइन है।",
"u40a5q": "एक दरवाज़ा, एक खिड़की और एक स्किम एक कॉम्बो में जोड़ो।",
"5rysj6": "Baka पर दो मिनट, बोर्ड से AuraNesian का मैप। तुम्हारी अपनी लाइन, पॉइंट के लिए। कम से कम 3,000 बैंक करो।",
"o8dp1u": "फ़्रीस्टाइल लाइसेंस से पहले का आख़िरी लेसन बिना किसी निर्देश का है: एक बड़ा मैप, दो मिनट, और जो भी लाइन तुम ढूँढो।",
"1jpgn9s": "पुल, पानी की टंकियाँ, बैंडो और पेड़: इनके बीच से एक लाइन सोचो।",
"1a6lzah": "गैप, क्लोज़ कॉल और ट्रिक को लंबे कॉम्बो में जोड़ो।",
"1mtdhjl": "बार-बार बैंक करो। दो मिनट एक क्रैश के लिए काफ़ी लंबा समय है।",
"1mvv2ua": "बोर्ड से, AuraNesian का बनाया।",
"1hf8p8y": "2 मिनट में 3,000 पॉइंट बैंक करो",
"1d5y9oa": "तुम्हारी अपनी लाइन।",
"1o9vwu4": "ज़्यादा कॉम्बो से बेहतर लंबे कॉम्बो हैं: एक मूव से सीधे अगले में।",
"1rndnup": "जोखिम वाले मूव के बाद नहीं, उससे पहले कॉम्बो बैंक करो।",
