"sgkomz": "दूसरे पायलट क्या देखते हैं",
"unh9nk": "तुम्हारा नाम, तुम्हारा अवतार, तुम्हारा क्वाड और जो तुम कहते हो। जिस नाम को शब्द सूची रोक देती है, वह बनावटी नाम के रूप में दिखता है। स्कूल सेफ़ रूम में सबका बनावटी नाम होता है, और सूचीबद्ध, स्कूल सेफ़ और स्ट्रीमर रूम तुम्हारा इंटरनेट पता कभी नहीं दिखाते।",
