"1xqmxfa": "दायाँ स्टिक कैमरा खिसकाता है, बायाँ चढ़ाता और घुमाता है। सिलेक्ट स्विच चुने हुए पायलट के पीछे चलता है, बैक तुम्हें वापस लाता है।",
