"1ra2hmr": "क्वाड को मारो तो उसकी हेल्थ घटती है। ख़ाली होने पर वह कंफ़ेटी के साथ पॉप होता है। हर पॉप एक पॉइंट है। बॉक्स लाल होते ही मिसाइल क्वाड का पीछा करती है।",
