"1bcu86u": "{0}{1} लगा हुआ है, पर यह ब्राउज़र उसे {2} {3} के साथ दिखाता है, और उड़ने के लिए चार चाहिए। EdgeTX रेडियो पर मॉडल का USB जॉयस्टिक मोड Classic करो, फिर रेडियो निकालकर दोबारा लगाओ।",
"r0fr7u": "एक जॉयस्टिक",
"1k67jhh": "{0} सिम तक नहीं पहुँच रहा। स्टिक हेल्प के लिए पॉज़ करो।",
"1g3lqvf": "अभी कोई रेडियो या गेमपैड इस ब्राउज़र तक नहीं पहुँच रहा। उसे लगाओ, जॉयस्टिक मोड में रखो और एक स्टिक हिलाओ: ब्राउज़र पेज को पैड तभी दिखाता है जब उस पर कुछ हिले।",
"l55p9d": "तुम्हारा सेव किया कैलिब्रेशन {0} को ऐसे एक्सिस से पढ़ता है जो इस पैड में नहीं है, इसलिए {1} कुछ नहीं पढ़ता। इसमें {2} हैं। स्टिक कैलिब्रेट करो उसे फिर से उसी के हिसाब से मैप करता है जो यह सच में भेजता है।",
"10cte0": "एक्सिस {0} स्टिक की तरह हिल रहा है, और सिम में उसे कोई नहीं पढ़ता। ब्राउज़र के पास तुम्हारी स्टिक है; सिम में वह ग़लत चैनल पर है। स्टिक कैलिब्रेट करो इसे क़रीब एक मिनट में ठीक कर देता है।",
"13f86ul": "एक्सिस {0} हिल रहा है, और सिम में उसे कोई नहीं पढ़ता। अगर यही वह स्टिक है जो काम नहीं कर रही, तो स्टिक कैलिब्रेट करो उसे सही चैनल पर रख देता है।",
"3hxjne": "वह {0} है, एक्सिस {1} पर, और वह सिम तक पहुँच रहा है।",
"4pid3q": "{0} स्टिक की तरह हिला, और सिम में {1} को कोई नहीं पढ़ता। यह ग़लत चैनल पर लगी स्टिक है, और स्टिक कैलिब्रेट करो इसे ठीक कर देता है।",
"13inlwb": "जो स्टिक काम नहीं कर रही उसे दोनों सिरों तक पूरा हिलाओ, और बार देखो।",
"2niqw0": "रेडियो पर: यह पेज खोलने से पहले, उसे लगाते समय USB जॉयस्टिक मोड चुनो, और उस पर चुना हुआ मॉडल जाँचो। हर चैनल क्या भेजेगा यह मॉडल तय करता है, और नया या ख़ाली मॉडल किसी स्टिक पर कुछ भी नहीं भेज सकता।",
"jem3gg": "तुम्हारा रेडियो {0} एक्सिस के रूप में आ रहा है।",
"rr1z7d": "अगर कोई बार नहीं हिलता: Windows",
"1j91r00": "देखो कि Windows को स्टिक दिखती है या नहीं: Windows और R दबाओ, joy.cpl टाइप करो, Enter दबाओ, अपना रेडियो चुनकर Properties खोलो, फिर उसे हिलाओ। अगर वह वहाँ हिलती है और यहाँ नहीं, तो इस स्क्रीन से बग रिपोर्ट करो और यही बताओ।",
"1qj9g8y": "अगर वह वहाँ भी नहीं हिलती, तो रेडियो उसे भेज ही नहीं रहा। उस Windows विंडो में कैलिब्रेट करने से ब्राउज़र जो पढ़ता है वह नहीं बदलता, इसलिए उसकी ज़रूरत नहीं।",
"1elsn67": "अगर कोई बार नहीं हिलता: Mac",
"193sfmd": "macOS में अपना कोई स्टिक टेस्ट नहीं है, इसलिए ये बार ही टेस्ट हैं। अगर स्टिक एक ब्राउज़र में हिलती है और दूसरे में नहीं, तो इस स्क्रीन से बग रिपोर्ट करो और बताओ कि किसमें।",
"1lg87ci": "अगर कोई बार नहीं हिलता: Linux",
"fk484m": "jstest-gtk या evtest दिखाता है कि रेडियो क्या भेज रहा है। अगर स्टिक वहाँ हिलती है और यहाँ नहीं, तो इस स्क्रीन से बग रिपोर्ट करो और यही बताओ।",
