"9s1w1d": "एक से पाँच स्टार, हर किसी की एक रेटिंग। तुम इसे बदल सकते हो या वापस ले सकते हो। पायलटों को नाम के पास औसत दिखता है, और बोर्ड सबसे अच्छे को पहले रख सकता है।",
