"d8h2dl": "जो ट्यून तुम उड़ाते हो उसे पब्लिक बोर्ड पर रखता है, एक छोटे कोड के साथ जिसे कोई भी पेस्ट करके उड़ा सकता है। यही ऊपर जाता है, और सिर्फ़ यही:",
"86leg4": "शामिल नहीं: तुम्हारे ग्राफ़िक्स, तुम्हारी स्टिक और रेडियो, तुम्हारा फ़्लाइट मोड और तुम्हारे लैप टाइम। ट्यून लोड करने से ये कभी नहीं बदलते।",
