"5slhk5": "इसके बारे में एक बात (वैकल्पिक)",
"152173s": "यह किस काम के लिए अच्छा है, पहले क्या आज़माएँ।",
"1g2zpqe": "इसके बारे में एक बात",
"zsv2pw": "लेखक के रूप में दिखेगा",
"m2bcgo": "शेयर करो",
"1pm6ttj": "इसे एक नाम दो, तीन या ज़्यादा अक्षर।",
"1idobjn": "शेयर हो रहा है",
"1t7t2wk": "शेयर हो गया",
"1tg83oy": "यह बोर्ड पर है। जो भी इसे उड़ाना चाहे उसे यह कोड भेजो।",
"1ic5sf9": "बोर्ड पर देखो",
