"oi32d0": "ट्यून लोड करो",
"1wgb6n": "एक शेयर कोड पेस्ट करो, जैसे k7mq-2xrt-9vwd। कुछ भी बदलने से पहले तुम्हें दिखता है कि ट्यून में क्या है, और तुम अपना वापस लगा सकते हो।",
"5gnh65": "शेयर कोड",
"lrfgp4": "खोजो",
"p9w0vv": "सारे ट्यून देखो",
