"1gm7ukv": "हटाया जा रहा है",
"z5o97m": "हटा दिया गया। कोड अब काम नहीं करता।",
"1204n16": "बोर्ड उसे हटा नहीं सका।",
"l60lk0": "लोड हो गया",
"om0kcs": "अभी तुम {0} उड़ा रहे हो। मेरा वापस लगाओ तुम्हारी पिछली सेटिंग लौटा देता है।",
"1vpg3mk": "मेरा वापस लगाओ",
"lo205": "तुम्हारी पिछली सेटिंग वापस आ गईं।",
"1ps9z3w": "शेयर कोड बारह अक्षरों और अंकों का होता है, जैसे k7mq-2xrt-9vwd।",
"d5w5cq": "खोज रहा है",
"1s2ni3o": "उस कोड वाला कोई ट्यून नहीं है।",
"1uwytf7": "बोर्ड तक नहीं पहुँचा जा सका।",
"1atyhbg": "व्हूप पर बदलें?",
"8uhxxq": "इस ट्रैक पर समय व्हूप से लिया जाता है। फ़ाइव इंच पर रहोगे तो समय नहीं लिया जाएगा।",
"wkeoh8": "बदलो (Y)",
"ypt803": "अभी नहीं (N)",
"4r9rjz": "सिर्फ़ व्हूप: सफ़ेद बॉक्स में लैंड करो",
"1dzhe8f": "स्टार्ट गेट से उड़कर निकलो",
"n816s8": "स्टार्ट पैड नहीं हैं, इसलिए पायलट प्लॉट के बाएँ किनारे से {0} m अंदर, उसकी आधी ऊँचाई पर, दाईं ओर मुँह करके शुरू करता है।",
"1t711z2": "रखने के लिए प्लॉट पर क्लिक करो।",
"ekduh5": "यह पॉइंटर के नीचे जो है उस पर खड़ा होता है: ज़मीन, छत, कंटेनर।",
"8o0928": "टूल हाथ में रहता है, इसलिए दूसरा क्लिक एक और रख देता है।",
"1329ksr": "सड़क का पहला नोड रखने के लिए ज़मीन पर क्लिक करो।",
"aaokh9": "यह अपने नोड से वैसे मुड़ती है जैसे कार चल सके।",
"1cziowk": "इसकी ताक़त",
"1kjx060": "। असली फ़ील्ड स्केल, असली रुकावटें, ऐसा प्लान जो तुम क्रू को दे सको।",
"ws88kv": "· ट्रैक {0}",
