"1rqldy2": "। andAgainFPV इसे इस सिम्युलेटर में लाए।",
"5k80a7": "चैप्टर {0}: पहली उड़ान, टाइम ट्रायल",
"1r5bgka": "कीबोर्ड रेस एंगल में उड़ती हैं। स्टिक झुकाव हैं। हाथ हटाओ तो सीधा हो जाता है।",
"151jezz": "खंभे के चारों ओर एक पूरा चक्कर या ज़्यादा, पेट ऊपर करके।",
"2h13ul": "फ़ाइव इंच ट्रैक",
"1ov5lw1": "{0} इंच ट्रैक",
"tda83r": "फ़ाइव इंच",
"1sss0ee": "चैप्टर {0}: पहली उड़ान, सीट पर",
"yajn08": "{0} इंच ट्रैक",
"1e05oqz": "ख़ाली मैदान पर बिल्डर खोलता है। उसके कैनवस पर जो भी था वह उसकी लोड सूची में रखा जाता है। तुम्हारे बनाए ट्रैक इसी ब्राउज़र में रहते हैं। इसे साफ़ करने पर, या दूसरे डिवाइस पर, तुम शून्य से शुरू करते हो। ट्रैक को पब्लिक बोर्ड पर रखने के लिए उसे पब्लिश करो।",
"1cdhqo": "Betaflight डिफ़ॉल्ट",
"1dudsha": "WebFPV की ओर से",
"cuy5ed": "इसका कोई भी हिस्सा बदलो और तुम एक अलग बोर्ड पर हो।",
"1iryycr": "Betaflight का अपना ट्यून, हल्के बदलाव के साथ: स्टिक का जवाब थोड़ा जल्दी, और रुकने के बाद वापस उछाल कम। ट्यून खोलता है, जहाँ ट्यून चुना जाता है और Betaflight के अपने स्लाइडर उसे ठीक करते हैं। तुम्हारे रेट्स रखे जाते हैं।",
"k6akiz": "फ़्रीस्टाइल मैप",
"10ufhmj": "{0} इंच",
"1r6qcm": "हल्का",
"3sm2ze": "तेज़",
"1xnvdto": "पूरे साइज़ का फ़्रीस्टाइल और रेस क्वाड: अपनी ताक़त के हिसाब से हल्का, बहुत तेज़, और उसे इस्तेमाल करने लायक बड़ा मैदान। हर एयरक्राफ़्ट अपना ट्यून, PID, पैक, वज़न और कैमरा रखता है: उसे बदलने पर उस मशीन की सेटिंग वैसी ही लौटती हैं जैसी तुमने छोड़ी थीं, या पहली बार उसकी स्टॉक सेटिंग, और बिल्डर बाहरी मैदान और लिविंग रूम के बीच बदल जाता है। तुम्हारे अपने रेट्स तुम्हारे साथ चलते हैं, जब तक वे अभी भी स्टॉक वाले न हों।",
"53x6f3": "बोर्ड से या किसी दूसरे पायलट से मिला शेयर कोड पेस्ट करो। पहले तुम्हें दिखता है कि उसमें क्या है, और तुम अपना वापस लगा सकते हो।",
"9ww08a": "मास्टर मल्टिप्लायर",
"1vv9xkm": "ट्रैकिंग, P और I",
"fetog5": "ड्रिफ़्ट और डगमगाहट, I",
"kyk48v": "डैम्पिंग, D",
"1roremq": "डायनामिक डैम्पिंग, D max",
"1e0pboe": "स्टिक रिस्पॉन्स, FF",
"we45r2": "पिच ट्रैकिंग",
"1dlny13": "पिच डैम्पिंग",
"1b1bac5": "नीचे का सब कुछ इसी ट्यून का है, और हर ट्यून अपना एडजस्टमेंट अलग रखता है।",
"193v7i": "सब कुछ एक साथ: P, I, D और फ़ीडफ़ॉरवर्ड सब साथ में बदलते हैं, अनुपात वही रहते हैं। यह \"इसे और सख़्त करो\" वाला नॉब है, और वही जिसकी माँग उड़ान के एहसास वाले फ़ीडबैक में थी। स्टॉक {0} पर है; पहले यहाँ जो सख़्त प्रीसेट आता था वह {1} पर था, जो लगभग उतना ही बड़ा क़दम है जितना वह फ़ीडबैक माँग रहा था।",
"c3fbrt": "स्टिक जो रेट माँगती है, क्वाड उसका कितनी ज़ोर से पीछा करता है। कम हो तो सुस्त और स्मूद, ज़्यादा हो तो सेटपॉइंट पर झट से पहुँचकर टिका रहता है।",
"amoq3u": "सिर्फ़ धीमी ग़लती वाला हिस्सा। बहुत कम हो तो बड़े मूव में एटिट्यूड से भटक जाता है; बहुत ज़्यादा हो तो लंबे स्टिक मूव में जमा होता है और स्टिक बीच में आते ही एक झटके में निकल जाता है। इस मॉडल पर झटका भटकाव से काफ़ी पहले आता है।",
"1kt9nne": "घुमाव का विरोध करता है, रुकना स्मूद करता है, प्रॉपवॉश शांत करता है। असली क्वाड पर D की क़ीमत मोटर की गर्मी और जाइरो का शोर है; इस मॉडल का जाइरो साफ़ है, इसलिए डैम्पिंग लगभग मुफ़्त है और सख़्त ट्यून इसे ऊँचा रखते हैं।",
"1wqluz6": "तेज़ मूव और स्टॉप के दौरान बेस D के ऊपर कितना अतिरिक्त D आता है। शून्य पर D स्थिर रहता है।",
"10nibr2": "फ़ीडफ़ॉरवर्ड सीधे स्टिक की हरकत पर ज़ोर लगाता है, कोई ग़लती आने से पहले ही। ज़्यादा हो तो तुरंत असर; बहुत ज़्यादा हो तो हर मूव की शुरुआत में आगे निकल जाता है। शून्य पर सिर्फ़ P और D से उड़ता है।",
"i42c2o": "रोल के मुक़ाबले पिच का P और I। क्वाड चौड़ाई से ज़्यादा लंबा होता है, इसलिए पिच में आम तौर पर कुछ प्रतिशत ज़्यादा रहता है।",
"1a9uio": "रोल के मुक़ाबले पिच का D, उसी वजह से जिससे पिच ट्रैकिंग है।",
"1eviq1n": "यहाँ से शुरू: Betaflight डिफ़ॉल्ट",
