"v2q9fn": "थ्रॉटल मिड",
"1xemf43": "थ्रॉटल एक्सपो",
"140ppwv": "{0} deg/s",
"1pq9vg": "{0}% स्टिक",
"bw3a2g": "नीचे के नंबर एक नाम से सेव करो और वे एक बार दबाने पर लौट आते हैं, दूसरे ट्रैक पर यही चाहिए होता है। प्रीसेट सिर्फ़ इस डिवाइस के इस ब्राउज़र में सेव होते हैं। साइट डेटा साफ़ करना, प्राइवेट विंडो, दूसरा ब्राउज़र या दूसरा डिवाइस, सब तुम्हें शून्य से शुरू कराते हैं, और न कोई अकाउंट है न कुछ अपलोड होता है।",
"g0jyc7": "छोटे स्टिक मूव पर क्वाड कितनी जल्दी जवाब देता है, यानी बीच में कर्व की ढलान।",
"idjhb0": "कम हो तो स्मूद लाइन के लिए शांत, ज़्यादा हो तो फुर्तीला और तेज़।",
"3gavi2": "यह आधी स्टिक पर रेट नहीं है: कर्व पढ़ो।",
"1mlk7hb": "Configurator इस कॉलम को Center Sensitivity कहता है।",
"1998vtg": "पूरी स्टिक पर क्वाड क्या करता है, ठीक वही।",
"njxqki": "Actual रेट्स इसी नंबर के लिए हैं: कर्व का सिरा वही नंबर है जो तुम टाइप करते हो, एक्सपो बीच में चाहे जो करे।",
"1x3rl5q": "स्टिक का कितना सफ़र बीच के पास ख़र्च होता है। शून्य यानी सेंटर सेंसिटिविटी से सिरे तक सीधी रेखा। ज़्यादा करने पर बीच नरम होता है और मैक्सिमम वही रहता है, इसीलिए इसे बदलने पर कर्व के सिरे नहीं हिलते।",
"7xrlm4": "थ्रॉटल को मिड पॉइंट के पास सपाट और सिरों पर खड़ा करता है, ठीक Betaflight का thr_expo। {0} फ़ैक्टरी की सीधी रेखा है।",
"h1vu9t": "इन नंबरों को नाम दो और वे एक बार दबाने पर लौट आते हैं। प्रीसेट सिर्फ़ इस डिवाइस के इस ब्राउज़र में सेव होते हैं। साइट डेटा साफ़ करना, प्राइवेट विंडो, दूसरा ब्राउज़र या दूसरा डिवाइस, सब तुम्हें शून्य से शुरू कराते हैं, और न कोई अकाउंट है न कुछ अपलोड होता है।",
