"1u0xx": "ट्रैक पब्लिश करने या टाइम पोस्ट करने के लिए ज़रूरी।",
"jky7ea": "{0} fps",
"sdsdu5": "की दबाने से लेकर उस फ़्रेम तक जिसने उसे पहली बार दिखाया, तुम्हारे पिछले {0} का मीडियन, जैसा यह ब्राउज़र बताता है; उसके बाद डिस्प्ले की अपनी देरी शामिल नहीं है। {1} Hz पर एक फ़्रेम {2} ms का है। यहाँ GPU एक फ़्रेम पर क़रीब {3} ms लेता है, फ़्रेम पेज के पीछे क़तार में लगते हैं (लो लेटेंसी व्यू इस्तेमाल में नहीं है)।",
"fqq2qr": "तुम्हारे अपने की प्रेस और क्लिक से लेकर उन्हें पहली बार दिखाने वाले फ़्रेम तक मापा जाता है, इसलिए मेन्यू इस्तेमाल करते करते यह भरता जाता है। यहाँ GPU एक फ़्रेम पर क़रीब {0} ms लेता है, फ़्रेम पेज के पीछे क़तार में लगते हैं (लो लेटेंसी व्यू इस्तेमाल में नहीं है)।",
