"opyx84": "कुछ नहीं खोला गया: \"{0}\" {1} कैनवस पर है और उसे रखा नहीं जा सका, क्योंकि लोकल स्टोरेज उपलब्ध नहीं है या भरा है। पहले इसे एक्सपोर्ट करो।",
"kuyw37": "\"{0}\" {1} कैनवस पर था, इसलिए अब वह लोड में है।",
