"qp3gzv": "\"{0}\" में सेव के बाद बदलाव हुए थे, इसलिए वे लोड में \"{1}\" नाम से हैं।",
"1yprcf0": "कुछ नहीं खोला गया: \"{0}\" में ऐसे बदलाव हैं जो आने वाले ट्रैक में नहीं हैं, और उन्हें रखा नहीं जा सका, क्योंकि लोकल स्टोरेज उपलब्ध नहीं है या भरा है। पहले इसे एक्सपोर्ट करो।",
"1o9kt4z": "\"{0}\" अब भी कैनवस पर है: उसे लोड में नहीं रखा जा सका, क्योंकि लोकल स्टोरेज उपलब्ध नहीं है या भरा है, इसलिए कुछ नया शुरू नहीं हुआ। पहले इसे और से एक्सपोर्ट करो, फिर नया दबाओ।",
