"dfet3": "खुल रहा है",
"zd85cj": "\"{0}\" को इस ब्राउज़र से डिलीट करो। जब तक यह सूची खुली है, पहले जैसा करो इसे वापस ला देता है।",
"9jdqur": "सेव किए मैप",
"opql46": "फ़ाइव इंच ट्रैक जो दूसरे पायलटों ने मैप और ट्रैक पर रखे हैं। किसी को खोलो तो वह तुम्हारी कॉपी है: कुछ भी बदलो, और अपने नाम से पब्लिश करो। असली उन्हीं का रहता है।",
"1d1l6my": "बोर्ड से उसके ट्रैक पूछे जा रहे हैं।",
"1ax09zh": "बोर्ड के किसी ट्रैक से शुरू करो",
"8ybw7e": "टूल में गेट शून्य से एक शुरू करता है।",
