"fqt564": "सड़क पर चलती एक कार, लूप पर लैप दर लैप, खुली सड़क पर जाकर वापस। इसे सड़क पर रखो और वहाँ तक सरकाओ जहाँ से यह शुरू करे। ड्रिफ़्ट चुनो तो यह ड्रिफ़्ट कार बन जाती है।",
