"m6rdhw": "स्पाइरल डाउन",
"sn63hu": "हर छेद अपना अलग गेट है। पहले ऊपर वाला, बगल से घूमकर, फिर दूसरे फ़ेस से नीचे वाला अगला छेद।",
"1xfzm27": "दो गेट। ऊपर वाले से होकर, उल्टे होकर, दूसरी दिशा में नीचे वाले से वापस। ट्रिपल में बीच वाला छूट जाता है।",
"v25afo": "दो गेट। नीचे वाले से होकर, आधे लूप में सामने से ऊपर और पार, दूसरी दिशा में ऊपर वाले से वापस। ट्रिपल में बीच वाला छूट जाता है।",
"1dnltfi": "दो गेट। नीचे वाला उड़ो, बगल से घूमो, फिर उसी फ़ेस से ऊपर वाला।",
"e8z1s": "तीन गेट। नीचे, घूमो, उसी फ़ेस से बीच वाला, घूमो, फिर ऊपर वाला।",
"1qmdk1c": "तीन गेट। ऊपर, घूमो, दूसरे फ़ेस से बीच वाला, घूमो, फिर नीचे वाला।",
"ud75v3": "दो गेट। ऊपर वाले से होकर, फ़्लिप, दूसरी दिशा में नीचे वाले से वापस।",
"1palox4": "दो गेट। ऊपर वाले से होकर, फ़्लिप, नीचे वाले से वापस। बीच का छेद नहीं गिना जाता।",
"vf0vzl": "दो गेट। नीचे वाले से होकर, आधे लूप में ऊपर और पार, दूसरी दिशा में ऊपर वाले से वापस।",
"1fngj6": "दो गेट। नीचे वाले से होकर, आधे लूप में ऊपर और पार, ऊपर वाले से वापस। बीच का छेद नहीं गिना जाता।",
