"1n5hw1j": "इस TinyLaps ट्रैक में उड़कर निकलने के लिए कोई रेस पॉइंट नहीं है, तो कोई लैप नहीं है। इन्हें TinyLaps में Race points के नीचे जोड़ो।",
"2mdt16": "एक से ज़्यादा बार उड़ा गया पॉइंट वही एक गेट है जो दोबारा उड़ा गया।",
