"1c4y7z8": "उसी दिशा में ऊपर और वापस नीचे: हर्डल, गेट या क्रॉसओवर के ऊपर से। नीचे और वापस ऊपर डिप है, किसी चीज़ के नीचे से।",
"5j8yhm": "टर्न",
"ef41m0": "सपाट टर्न, बाएँ या दाएँ: चौथाई, हेयरपिन या पूरा ऑर्बिट।",
