"1b8l35v": "ऐसा टर्न जो घूमते हुए चढ़ता है। रेडियस ऊपर मौजूद किसी भी चीज़ से सीमित रहता है।",
"kxfysu": "उतरता टर्न",
"74urkb": "ऐसा टर्न जो घूमते हुए ऊँचाई खोता है। इसके लिए ख़र्च करने लायक़ ऊँचाई चाहिए।",
"6nhbo6": "उल्टे होने तक आधा रोल और खींचकर निकलो: दिशा पलट जाती है और लाइन जहाँ से शुरू हुई उससे नीचे ख़त्म होती है।",
"18nvo8l": "ऊपर खींचो, पार जाओ और रोल करके सीधे हो जाओ: दिशा पलट जाती है और लाइन जहाँ से शुरू हुई उससे ऊपर ख़त्म होती है।",
"1mhlz1": "खड़ा गोला: ऊपर, पार, नीचे और उसी ओर बाहर जिस ओर से अंदर गया, उसी ऊँचाई पर जहाँ से शुरू हुआ।",
"19szesg": "कॉर्कस्क्रू",
"1nr6ya1": "बगल का लूप जो अगले गेट को नज़र में रखता है: उड़ान की लाइन के चारों ओर एक रोल, बाएँ या दाएँ, पहले ऊपर या पहले नीचे।",
"sib5hn": "नाक नीचे करके खड़ी ढलान वाली लाइन पर और काफ़ी नीचे जाकर लेवल हो जाओ।",
