"hrh2al": "खड़ी चढ़ाई, फिर पार होकर लेवल, काफ़ी ऊपर।",
"ln7q9f": "वीव: लाइन के बारी-बारी से बाएँ और दाएँ, जितनी बार तुम माँगो।",
