"b5oxlq": "Drone Nationals के प्लान का हर्डल: फ़्लैगों के बीच 4 m और 1 m ऊँचा बोर्ड।",
"12gekmz": "MultiGP का हर्डल: 10 फ़ुट चौड़ा और 5 फ़ुट ऊँचा पैनल।",
"onghcv": "10 गुणा 5 फ़ुट का हर्डल जिसके एक सिरे पर 5 फ़ुट और ऊँचा पोल खड़ा है: लाइन बोर्ड के ऊपर से और पोल के चारों ओर जाती है।",
"17mgy9g": "सुपर",
"1qgjfzi": "बहुत बड़ा हर्डल, स्टैंडर्ड से दुगना, 20 फ़ुट चौड़ा और 10 फ़ुट ऊँचा: इसे पार करने के लिए लैप को चढ़ना पड़ता है। MultiGP इसका कोई नंबर नहीं देता, तो यह हर्डल का दुगना है; नाप डिटेल में हैं।",
"1dfeka7": "ऊपर से",
"1s8j42k": "टॉप से एक मीटर ऊपर, आराम से जगह छोड़कर ऊपर से हॉप",
"1env7gx": "स्किम",
"h7e29o": "टॉप से एक हाथ ऊपर: जितना नीचे से बिना छुए उड़ा जा सके",
"czu9nx": "नीचे से",
"1wsqdgg": "बार के नीचे, उसके पैरों के बीच। नीचे से जाने की जगह सिर्फ़ बार हर्डल में होती है",
"15ym8cp": "बार के ऊपर से",
"140j0ez": "दो अलग गेट चुनो।",
"1krfxs5": "सिर्फ़ एक-एक ओपनिंग वाले गेट जोड़े जा सकते हैं: अक्षर, क्यूब, वॉल या स्टैक नहीं।",
"14e83cq": "दोनों गेटों का मुँह अलग दिशा में है। पहले एक को घुमाकर दूसरे जैसा करो: ये एक सपाट ओपनिंग के रूप में गिने जाते हैं।",
"1vms63u": "दोनों गेट एक ही तल में नहीं हैं: एक दूसरे से काफ़ी आगे है। पहले इन्हें सीध में लाओ।",
"1sc2w7e": "दोनों में से कोई गेट उड़ान के क्रम में नहीं है। पहले एक को ट्रैक में जोड़ो: जोड़ा हुआ गेट उसकी जगह लेता है।",
"lnrfja": "स्पाइरल अप बाएँ",
"1iv2kkb": "स्पाइरल अप दाएँ",
"9m8yz9": "ऊँचाई का नक़्शा देखने के लिए गेटों को उड़ान के क्रम में रखो",
"n46s56": "स्टार्ट/फ़िनिश गेट",
"ltzvg8": "ज़मीन का गेट, और वही जिस पर घड़ी शुरू और बंद होती है। हर ऑफ़िशियल डायग्राम में हरा बनाया जाता है।",
"18sq0os": "सिंगल गेट",
"19fzmv8": "एक चौकोर जिसकी निचली बार फ़र्श पर है।",
"lioz72": "साथ-साथ वाले गेट",
"13uy9mp": "दो या तीन गेट एक क़तार में, खड़े पाइप साझा करते हुए, बीच से बीच तक 30 इंच।",
"1kwun9": "डबल स्टैक गेट",
"q8323j": "दो गेट एक के ऊपर एक। ऊपर वाला कम से कम 42 इंच ऊपर है।",
"wjm0hc": "ट्रिपल गेट स्टैक",
"36bs9b": "तीन ऊँचा। सबसे ऊपर वाला कम से कम 69 इंच ऊपर है।",
"1ncy5eu": "ऊँचा गेट",
"df1mpl": "ज़मीन के गेटों के ऊपर उठाया गया गेट, जिसका निचला हिस्सा कम से कम 56 इंच ऊपर है।",
"pg6wzg": "आड़ा गेट",
"ug5p2j": "आड़े तल में रखा गेट। इसे क्यूब गेट भी कहते हैं। इसमें से नीचे की ओर उड़ो।",
"18bcq13": "खड़ा पोल",
"1ay4ph7": "एक खड़ा पाइप जिसके चारों ओर उड़ा जाता है। हर डायग्राम के प्लान में लाल बिंदु।",
