"1m3kezv": "{0} हर गैप उड़ान के क्रम में अपना अलग गेट है: पास बताता है कि वह किसमें से जाता है।",
"1ugsv61": "अक्षर की चौड़ाई",
"1s7eddk": "अक्षर की ऊँचाई",
"vq42m7": "{0}। पाइप 2 इंच का है, और अक्षर का पाइप ठोस है।",
"18ku1py": "इसे गेट बनाओ",
"h5sgwm": "जहाँ मुख्य गैप है वहाँ एक सादा गेट, उतना ही बड़ा। किसी और गैप से गुज़रने वाला पास क्रम से हटा दिया जाता है।",
"q7q9fq": "फ़्रेम",
"r64mng": "पाइप हटा दिया गया है: गैप अब भी स्कोर देते हैं और जलते हैं, और टकराने को कुछ नहीं है। कमरे में यह सिर्फ़ अपने गैप के रूप में दिखता है।",
"s9vozj": "अक्षर पाइप से बना है। इसे अदृश्य करो तो इसके गैप टारगेट बने रहते हैं और उनके चारों ओर कुछ नहीं बना होता।",
"1rkao2q": "पाइप वापस लगाओ",
"1ezapez": "इसे अदृश्य करो",
"1h88uzq": "हर साइड अपना अलग पाइप है: ऊपरी बार सबसे ऊपर की ओपनिंग के ऊपर है और निचली बार सबसे नीचे वाली के नीचे, और खंभा हर ओपनिंग के लिए एक टुकड़ा है। बाएँ और दाएँ बटन पूरा खंभा हटाते हैं; उनके नीचे के बटन एक ओपनिंग का टुकड़ा हटाते हैं। एक हटा दो तो भी ओपनिंग स्कोर देती हैं। 3D व्यू में चुने हुए गेट के किसी पाइप पर क्लिक करके Delete दबाओ: इससे सिर्फ़ वही टुकड़ा हटता है जिस पर तुमने क्लिक किया। बाएँ और दाएँ वैसे हैं जैसे गेट के सामने से दिखते हैं, ऊपरी बार के फ़्लैग की तरह।",
"3wzvo0": "हर साइड अपना अलग पाइप है। एक हटा दो तो भी ओपनिंग स्कोर देती और जलती है, और वहाँ टकराने को कोई पाइप नहीं रहता। 3D व्यू में चुने हुए गेट के किसी पाइप पर क्लिक करके Delete दबाओ। बाएँ और दाएँ वैसे हैं जैसे गेट के सामने से दिखते हैं, ऊपरी बार के फ़्लैग की तरह।",
"1vhm01f": "{0} हटाओ",
"80wioy": "{0} वापस लगाओ",
"a9ak0k": "{0} का टुकड़ा हटाओ",
"1mtqtr1": "{0} का टुकड़ा वापस लगाओ",
"1302s3v": "फ़्रेम वापस लगाओ",
"ka4wbv": "हर साइड वापस लगाओ",
"103wg51": "हर साइड हटाओ, और फ़्लैग भी अगर है: ओपनिंग अब भी स्कोर देती और जलती है, और टकराने को कुछ नहीं रहता।",
"e2847m": "ऊपरी बार का फ़्लैग",
"127gict": "हर्डल पर पेनेंट कहाँ खड़े होते हैं: उसके सिरों पर। मस्तूल की ऊँचाई नीचे नाप में दी गई फ़्लैग की ऊँचाई है, और मस्तूल ठोस है।",
"17wx66j": "ऊपरी बार पर पेनेंट कहाँ खड़ा होता है, जैसा गेट के सामने से दिखता है। \"ऊपर\" चुनने पर एक मस्तूल बोर्ड के बीच में लगता है, ठीक ओपनिंग के ऊपर। मस्तूल की ऊँचाई नीचे नाप में दी गई फ़्लैग की ऊँचाई है, और मस्तूल ठोस है: ऊपरी रेल पर डाइव करता पायलट इससे टकरा सकता है।",
"d0y2y3": "छेद",
"1w31kfz": "हरा चौकोर वह जगह है जिसमें से तुम्हें उड़ना है। प्लान पर गोल हैंडल खींचकर इसे मार्कर के चारों ओर कहीं भी घुमाओ, पूरे चक्कर में। \"तरफ़ पलटो\" इसे उल्टी तरफ़ भेज देता है, और \"फिर से निकालो\" इसे अपने आप वाले नियम को वापस सौंप देता है, यानी टर्न का बाहरी हिस्सा।",
"1wg2ncb": "फ़ेस पलटो",
"172xku9": "तरफ़ पलटो",
"3d7qa3": "शॉर्टकट: X",
"1tdvisw": "फिर से निकालो",
"qqpglk": "इसे अपने आप वाले नियम को वापस सौंपो, जो इसे पिछले एलिमेंट से अगले तक की लाइन की दिशा में कर देता है।",
"1c086it": "कुछ नहीं चुना। एडिट करने के लिए किसी एलिमेंट पर क्लिक करो, या कई चुनने के लिए ख़ाली ज़मीन पर बॉक्स खींचो।",
"3eggiu": ": RaceGOW, कमरे में 65 mm व्हूप के लिए। गेट 24 से 28 in, पास-पास के गेट बीच से बीच तक 30 in, और सबसे छोटे गेट पर पूरा ट्रैक 4 गुणा 6 ft के अंदर, जो गेटों के साथ बड़ा होता है। हर पीस कमरे के बीच से इंच में नापा जाता है, और ग्रिड एक इंच का है।",
