"zafenl": "एक पीस: गेट जो अपने पाइप साझा करते हैं। इसमें एक फ़ेस से अंदर और दूसरे से बाहर उड़ा जाता है, और कौन से, यह उड़ान के क्रम वाला टूल बदलता है। हिलाने के लिए इसे खींचो। Q और E इसे घुमाते हैं। ऐरो की इसे थोड़ा खिसकाती हैं।",
