"d388vx": "क्रम में",
"hwn39s": "सबसे तंग मोड़",
"s659t5": "बताने को कुछ नहीं। लाइन हर एलिमेंट से सही दिशा में गुज़रती है, मैदान के अंदर, बैरियर से दूर।",
"1jtc0ud": "चेतावनियाँ सिर्फ़ सलाह हैं। यहाँ कुछ भी सेव या एक्सपोर्ट को नहीं रोकता।",
