"1kbiosn": "नाम वाले गैप",
"1j5ormg": "सड़कें",
"yib3lg": "गाड़ियाँ",
"908nna": "प्लॉट पर",
"15pazei": "बताने को कुछ नहीं। दो चीज़ों के बीच की हर जगह या तो बंद है या उड़ने लायक़ चौड़ी, स्टार्ट साफ़ है, और हर नाम वाला गैप खुला है।",
