"1248f0f": "गाड़ी: किसी सड़क पर क्लिक करो",
"18fby00": "सेल किट लोड नहीं हुई ({0}), तो 3D व्यू हर एसेट को उसके सादे ठोस आकारों के रूप में बनाता है। मैप पर कोई असर नहीं।",
"hrcfdw": "3D व्यू फ़्रीस्टाइल एसेट लोड नहीं कर सका ({0}), तो यह प्लॉट को उनके बिना दिखाता है। 2D व्यू पर कोई असर नहीं।",
"ak6mu4": "नंबर {0}, इस पीस से गुज़रने वाले {1} पास में से एक। देखने के लिए क्लिक करो, दूसरी जगह देने के लिए डबल क्लिक करो।",
"1l6mpsh": "उड़ान के क्रम में नंबर {0}। देखने के लिए क्लिक करो, दूसरी जगह देने के लिए डबल क्लिक करो।",
"ne1jb": "उड़ान के क्रम में जगह",
"1d07sei": "3D प्रीव्यू सड़कें और कारें नहीं बना सका ({0})। मैप पर कोई असर नहीं।",
