"ky4lc5": "रोको",
"7an3sj": "कारें रोको और उन्हें वहीं वापस रखो जहाँ से वे शुरू करती हैं",
"lf5j6j": "कारों को उनकी सड़कों पर चलाओ, जैसे सिम्युलेटर चलाएगा",
