"hmu6f5": "{0} अपने पाइप के लिए बहुत छोटा है: जिस गैप से इसे उड़ा जाता है, उसके चारों ओर पाइप आने के बाद उसमें कुछ नहीं बचता, तो वहाँ कुछ स्कोर नहीं हो सकता। अक्षर को बड़ा करो।",
"1xhn5ud": "{0} का गैप सबसे चौड़ी जगह पर सिर्फ़ {1} m है, जबकि स्टैंडर्ड गेट का 1.5 m होता है, तो क्वाड के पास इसे उड़ने की जगह कम है। अगर ट्रैक में यही चाहिए तो इसे अनदेखा करो; नहीं तो अक्षर को बड़ा करो।",
"amkahr": "{0}। {1} का कोई एंट्री फ़ेस सेट नहीं है, तो लाइन ने एक का अंदाज़ा लगाया।",
"1f6an1h": "{0} मैदान के बाहर खड़ा है।",
"up72l1": "{0} और {1} एक ही जगह पर हैं, तो उनके बीच लाइन की कोई दिशा नहीं है।",
"1fgg8vv": "{0} का मुँह {1} से उल्टी ओर है। लाइन इससे पीछे की ओर निकलती है। फ़ेस पलटने के लिए X दबाओ।",
"19psiq7": "{0} का मुँह वापस {1} की ओर है। लाइन इस पर पीछे से पहुँचती है। फ़ेस पलटने के लिए X दबाओ।",
"1xkwf83": "लैप {0} से उल्टी ओर निकलता है। स्टार्ट पैड घुमाओ, या ट्रैक का क्रम बदलो।",
"1vv4mnm": "लैप {1} के बाद {0} पर उसके सामने से लौटता है। वह फ़ेस पलटो, या आख़िरी एलिमेंट को उसके पीछे ले जाओ।",
"1gf0z7v": "रेस की स्पीड पर क्वाड यह नहीं उड़ता। अगर ट्रैक में यही चाहिए, तो मैदान की सेटिंग में \"इससे कम रेडियस पर चेतावनी\" घटाओ।",
"1bw4o5i": "यह कुछ भी नहीं उड़ सकता।",
