"qlb5lu": "लैप में {0} m पर लाइन मैदान से बाहर निकल जाती है।",
"trp2du": "लैप में {0} m पर लाइन ज़मीन के नीचे चली जाती है।",
"63njfk": "{0} और {1} एक दूसरे से {2} m दूर खड़े हैं, उड़ान के क्रम में एक के बाद एक, तो एक ही पास दोनों तक पहुँच सकता है। रेस {3} को {4} m और उड़ने के बाद ही गिनती है। अगर इनके बीच एक लैप चाहिए, तो एक को दूर ले जाओ।",
"1l1fncv": "{0} का अंत {1} से उल्टी ओर मुँह करके होता है, तो उस तक पहुँचने के लिए लाइन को वापस अपने ऊपर मुड़ना पड़ता है। {2} को वहाँ रखो जहाँ फ़िगर ख़त्म होता है, या फ़िगर को उल्टी ओर घुमाओ।",
"1ozh84i": "{0} से लाइन पीछे की ओर {1} में निकलती है, तो उसे शुरू करने के लिए लाइन को वापस अपने ऊपर मुड़ना पड़ता है। {2} को उल्टी ओर घुमाओ, या फ़िगर को हिलाओ।",
