"1xr491b": "{0} {2} के मुक़ाबले सीध से {1} डिग्री हटा हुआ है। हर गेट ट्रैक के दो एक्सिस में से एक की ओर मुँह करता है: इसे उनके हिसाब से समकोण पर घुमाओ।",
