"1x8yhyt": "{0} स्टार्ट पैड के ऊपर से जाती है, तो इस पर चलती कार लॉन्च का इंतज़ार करते क्राफ़्ट के आर-पार निकलती है। सड़क या पैड हिलाओ।",
"11r26o9": "{0} वहाँ से एक मीटर के अंदर से गुज़रती है जहाँ क्राफ़्ट शुरू करता है, तो इस पर चलती कार पैड छोड़ने से पहले ही क्राफ़्ट को छू जाती है। सड़क या पैड हिलाओ।",
