"5s8foe": "{0} और {1} दोनों {2} पर हैं, जो खुली सड़क है: हर कार उसके बीच में सिरे तक और वापस चलती है, तो दोनों आमने-सामने मिलती हैं और एक दूसरे के आर-पार निकल जाती हैं। सड़क को लूप में बंद करो, या इस पर एक ही कार रखो।",
"1c7ews2": "{0} और {1} {2} की एक ही लेन में उल्टी दिशाओं में चलती हैं, तो वे आमने-सामने मिलती हैं और एक दूसरे के आर-पार निकल जाती हैं। सड़क को दो लेन दो, या इनमें से एक को पलट दो।",
